  const NEIGHBORHOODS = [{"name": "Kadıköy", "desc": "The shore the ancients called blind, and the side of the water Istanbul now crosses to for dinner", "maps": "https://www.google.com/maps/search/?api=1&query=Kad%C4%B1k%C3%B6y+%C4%B0skelesi+Istanbul"}, {"name": "Moda", "desc": "Wooden villas built by three communities, and a 1917 pier that now lends out books", "maps": "https://www.google.com/maps/search/?api=1&query=Moda+%C4%B0skelesi+Kad%C4%B1k%C3%B6y+Istanbul"}, {"name": "Yeldeğirmeni", "desc": "Windmills once, then the first apartment blocks on this shore, now murals on every gable wall", "maps": "https://www.google.com/maps/search/?api=1&query=Yelde%C4%9Firmeni+Kad%C4%B1k%C3%B6y+Istanbul"}, {"name": "Üsküdar", "desc": "The golden city of the Greeks, and the shore where the sultan's caravan set out for Mecca", "maps": "https://www.google.com/maps/search/?api=1&query=%C3%9Csk%C3%BCdar+%C4%B0skelesi+Istanbul"}, {"name": "Kuzguncuk", "desc": "A mosque, a synagogue and churches on one short street, in a village of wooden houses", "maps": "https://www.google.com/maps/search/?api=1&query=Kuzguncuk+%C4%B0skelesi+Istanbul"}, {"name": "Beyoğlu / Pera", "desc": "The avenue was called the Grand Rue de Péra, and for most of its life it was not Turkish", "maps": "https://www.google.com/maps/search/?api=1&query=%C3%87i%C3%A7ek+Pasaj%C4%B1+Beyo%C4%9Flu+Istanbul"}, {"name": "Cihangir", "desc": "A dead prince's mosque, then the writers and the cats, now a handful of small serious kitchens", "maps": "https://www.google.com/maps/search/?api=1&query=Cihangir+Camii+Beyo%C4%9Flu+Istanbul"}, {"name": "Nişantaşı", "desc": "Named for the stones that recorded how far a sultan's arrow flew", "maps": "https://www.google.com/maps/search/?api=1&query=Ni%C5%9Fanta%C5%9F%C4%B1+%C5%9Ei%C5%9Fli+Istanbul"}, {"name": "Karaköy and Galata", "desc": "A Genoese city-state with its own walls, and a banker's staircase down to the cruise front", "maps": "https://www.google.com/maps/search/?api=1&query=Kamondo+Merdivenleri+Karak%C3%B6y+Istanbul"}, {"name": "Balat and Fener", "desc": "Jewish Balat and Greek Fener side by side on the Golden Horn, and a red school above both", "maps": "https://www.google.com/maps/search/?api=1&query=Balat+Fatih+Istanbul"}, {"name": "Arnavutköy", "desc": "The fastest water on the strait, an Albanian name, and a scented strawberry that lost its fields", "maps": "https://www.google.com/maps/search/?api=1&query=Arnavutk%C3%B6y+%C4%B0skelesi+Istanbul"}, {"name": "Bebek", "desc": "The calmest bay on the European shore, and a khedive's palace demoted to a consulate", "maps": "https://www.google.com/maps/search/?api=1&query=Bebek+Park%C4%B1+Be%C5%9Fikta%C5%9F+Istanbul"}, {"name": "Tarabya", "desc": "Poison, renamed cure, then rented out to the ambassadors for the summer", "maps": "https://www.google.com/maps/search/?api=1&query=Tarabya+Koyu+Sar%C4%B1yer+Istanbul"}];
  const WALKS = [{"name": "The vapur: Eminönü to Kadıköy", "desc": "The best room in Istanbul moves, costs a commuter fare and serves tea on deck", "maps": "https://www.google.com/maps/search/?api=1&query=Emin%C3%B6n%C3%BC+Kad%C4%B1k%C3%B6y+Vapur+%C4%B0skelesi+Istanbul"}, {"name": "Karaköy or Eminönü to Üsküdar", "desc": "The shortest hop to Asia: go over in daylight and come back west into the sunset", "maps": "https://www.google.com/maps/search/?api=1&query=%C3%9Csk%C3%BCdar+%C4%B0skelesi+Istanbul"}, {"name": "The Golden Horn line: Üsküdar to Eyüpsultan", "desc": "One boat, nine piers, and the front door of every Golden Horn walk in this guide", "maps": "https://www.google.com/maps/search/?api=1&query=Karak%C3%B6y+Hali%C3%A7+%C4%B0skelesi+Istanbul"}, {"name": "Arnavutköy to Bebek", "desc": "Painted timber houses standing in the water, then a bay full of boats at the end", "maps": "https://www.google.com/maps/search/?api=1&query=Arnavutk%C3%B6y+%C4%B0skelesi+Istanbul"}, {"name": "Kuzguncuk's one street", "desc": "A mosque, a synagogue and churches on one short road, and a gravestone from 1562", "maps": "https://www.google.com/maps/search/?api=1&query=Kuzguncuk+%C4%B0skelesi+Istanbul"}, {"name": "Moda and the Kadıköy sea walk", "desc": "The flat seafront the Asian side actually uses, pointed straight at the sunset", "maps": "https://www.google.com/maps/search/?api=1&query=Kad%C4%B1k%C3%B6y+%C4%B0skelesi+Istanbul"}, {"name": "Fener: the Patriarchate and the iron church", "desc": "Orthodoxy's senior see behind an iron gate, then a whole church cast in Vienna", "maps": "https://www.google.com/maps/search/?api=1&query=Fener+Rum+Patrikhanesi+Istanbul"}, {"name": "Balat: Ahrida and the Jewish quarter", "desc": "Eighteen synagogues once, three still working, and one with a bimah shaped like a ship's prow", "maps": "https://www.google.com/maps/search/?api=1&query=Ahrida+Sinagogu+Balat+Istanbul"}, {"name": "Eyüpsultan and the hill above it", "desc": "A pilgrimage mosque, a cemetery climbing the slope, and a cable car to the view", "maps": "https://www.google.com/maps/search/?api=1&query=Ey%C3%BCp+Sultan+%C4%B0skelesi+Istanbul"}];
  const WORK_SPOTS = [{"name": "Çınaraltı, Çengelköy", "desc": "Chairs set under a plane tree said to be nearly a thousand years old, on the Asian shore", "maps": "https://www.google.com/maps/search/?api=1&query=%C3%87%C4%B1naralt%C4%B1+%C3%87ay+Bah%C3%A7esi+%C3%87engelk%C3%B6y+Istanbul"}, {"name": "Pierre Loti Kahvesi", "desc": "Tea on a hill above the graves, the whole Golden Horn laid out below, and a cable car to get up", "maps": "https://www.google.com/maps/search/?api=1&query=Pierre+Loti+Kahvesi+Ey%C3%BCpsultan+Istanbul"}, {"name": "Moda Aile Çay Bahçesi", "desc": "The whole of Kadıköy, three generations of it, facing the Marmara over a backgammon board", "maps": "https://www.google.com/maps/search/?api=1&query=Moda+Aile+%C3%87ay+Bah%C3%A7esi+Kad%C4%B1k%C3%B6y+Istanbul"}, {"name": "İnci Pastanesi", "desc": "One dessert, one recipe, since the 1940s, and a redevelopment that moved the whole shop round the corner", "maps": "https://www.google.com/maps/search/?api=1&query=%C4%B0nci+Pastanesi+Mis+Sokak+Beyo%C4%9Flu+Istanbul"}, {"name": "Markiz (ex-Lebon)", "desc": "Four Art Nouveau seasons were ordered from France; two of them are still on the wall", "maps": "https://www.google.com/maps/search/?api=1&query=Markiz+%C4%B0stiklal+Caddesi+Beyo%C4%9Flu+Istanbul"}, {"name": "Kronotrop, Cihangir", "desc": "Sixteen and a half hours a day of table, on the Cihangir slope above Tophane", "maps": "https://www.google.com/maps/search/?api=1&query=Kronotrop+Cihangir+Firuza%C4%9Fa+Istanbul"}, {"name": "Montag Coffee Roasters", "desc": "The roaster most of the scene credits as the pioneer, and the Kadıköy room is where you sit", "maps": "https://www.google.com/maps/search/?api=1&query=Montag+Coffee+Roasters+Muvakk%C4%B1thane+Kad%C4%B1k%C3%B6y+Istanbul"}, {"name": "Petra Roasting Co., Bebek", "desc": "Where the shore walk ends and the morning's work starts, from half past seven", "maps": "https://www.google.com/maps/search/?api=1&query=Petra+Roasting+Co.+Bebek+Istanbul"}, {"name": "Atatürk Kitaplığı", "desc": "Eldem's 1970s library above Taksim: a research collection now, no longer an open reading room", "maps": "https://www.google.com/maps/search/?api=1&query=Atat%C3%BCrk+Kitapl%C4%B1%C4%9F%C4%B1+G%C3%BCm%C3%BC%C5%9Fsuyu+Istanbul"}, {"name": "SALT Galata", "desc": "The Imperial Ottoman Bank's head office, emptied of money and handed to readers for nothing", "maps": "https://www.google.com/maps/search/?api=1&query=SALT+Galata+Bankalar+Caddesi+Karak%C3%B6y+Istanbul"}, {"name": "Çadır Köşkü, Yıldız Park", "desc": "A sultan's walled garden, two pavilions turned cafés, and a glass of çay under the trees", "maps": "https://www.google.com/maps/search/?api=1&query=%C3%87ad%C4%B1r+K%C3%B6%C5%9Fk%C3%BC+Y%C4%B1ld%C4%B1z+Park%C4%B1+Be%C5%9Fikta%C5%9F+Istanbul"}];
