  const PHOTOS = [{"src": "/terroir/Istanbul-Bogazici/img/ph-1-vapur-bosphorus.jpg", "caption": "The commuter crossing. Şehir Hatları still works the strait, and the deck of a vapur is the cheapest good hour in the city.", "credit": "Tarık Kaan Muslu · CC BY-SA 4.0 · Wikimedia Commons"}, {"src": "/terroir/Istanbul-Bogazici/img/ph-2-galata-bridge-anglers.jpg", "caption": "Rods over the rail of the Galata Bridge, the restaurants packed on the deck beneath.", "credit": "Diego Delso · CC BY-SA 4.0 · Wikimedia Commons"}, {"src": "/terroir/Istanbul-Bogazici/img/ph-3-grand-bazaar.jpg", "caption": "The Grand Bazaar. The honest advice is knowing which lanes still make things and which only sell.", "credit": "Diego Delso · CC BY-SA 4.0 · Wikimedia Commons"}];
  const GEMS = [{"id": "gem-1-yanyal-fehmi-lokantas", "name": "Yanyalı Fehmi Lokantası", "tag": "Food gem", "title": "The restaurant that came the other way", "story": "Yanyalı means 'from Yanya', the Ottoman name for Ioannina, in Greece. The founder's family made the crossing in the opposite direction to the people this city lost; the lokanta's own card, in the tables, has the rest.", "body": "Yanyalı Fehmi Lokantası has been open in Kadıköy since 1919, founded by Fehmi Efendi, whose family migrated from Yanya — Ioannina, in Greece. 'Yanyalı' means 'from Yanya'. In a city whose Greek community was removed by a wealth tax, a pogrom and an expulsion, the oldest surviving lokanta on the Asian side was founded by a family who came the other way in the same exchange.", "where": "Yanyalı Fehmi Lokantası has been open in Kadıköy since 1919, founded by Fehmi Efendi, whose family migrated from Yanya — Ioannina, in Greece", "pattern": "Yanyalı Fehmi Lokantası"}, {"id": "gem-2-why-the-meyhane-looks-the-way-it-d", "name": "Why the meyhane looks the way it does", "tag": "Food gem", "title": "Why the meyhane looks the way it does", "story": "The long table of cold mezes, the rakı with water, the musicians between the tables: a minority institution that outlived its minority. The essay and the food-history fold tell how.", "body": "Under the Ottoman millet system the non-Muslim communities governed their own affairs — and because alcohol was forbidden to Muslims, the licence to run a drinking house was effectively a non-Muslim one. The long table of cold mezes, the rakı poured with water, the fasıl musicians moving between tables: not a Turkish invention that happens to be old, but a minority institution that outlived the minority.", "where": "Why the meyhane looks the way it does", "pattern": "meyhane"}];
  const TABLES = {"grande": {"title": "La Grande Table", "desc": "The tables you clear an evening for: the city's only two-star, two one-stars that argue about what Anatolian cooking may become, and the new wave that opened into a currency crisis and cooked anyway.", "sections": [{"label": "La Crème de la Crème", "desc": "The three tables Istanbul is judged on: the two-star in Bomonti, the Pera roof, and the rebuilt classics in Karaköy. Book weeks out.", "ids": ["turk-fatih-tutak", "mikla", "neolokal"]}, {"label": "The 2026 wave", "desc": "The new guard: a fire inside a 19th-century passage, a starred chef's comfort food, and a neo-bistro across the water.", "ids": ["kontuar", "todos-los-dias", "basta-neo-bistro"]}]}, "petite": {"title": "La Petite Table", "desc": "Where this guide actually lives: the day-off addresses, the fire counters, the tradesman's tables, the breakfast houses, the kitchens of every direction the city once ruled, and the rooms that have fed it for a century.", "sections": [{"label": "Where the chefs eat", "desc": "Not the rankings: the addresses the city's own cooks give for their days off, and who says so.", "ids": ["nazende-cadde", "asmali-cavit", "balikci-kahraman"]}, {"label": "The fire counters — Ocakbaşı", "desc": "You sit at the coals and the usta cooks in front of you: the most Istanbul way to eat, on three counters.", "ids": ["tam-ocakbasi", "mesai", "ahmet-ustam-ocakbasi"]}, {"label": "Esnaf lokantası — the tradesman's table", "desc": "The rooms that matter more: a twelve-seat fire with a star, the Anatolian field-recording kitchen, and Antakya in exile.", "ids": ["araf-istanbul", "ciya-sofrasi", "casius-antioch-kitchen"]}, {"label": "Kahvaltı — the breakfast tables", "desc": "The breakfast table done seriously: a Van serpme house, the honest end of the Beşiktaş street, and kaymak by the water.", "ids": ["van-kahvalti-evi", "cakmak-kahvalti-salonu", "emirgan-sutis-emirgan"]}, {"label": "The other kitchens — Anatolia & beyond", "desc": "Siirt, Crete, the Black Sea and Damascus: the city eats in every direction it once ruled.", "ids": ["siirt-seref-buryan", "giritli", "hayvore", "saruja"]}, {"label": "The old houses", "desc": "1890, 1912, 1919: the rooms where a century sits down to eat with you.", "ids": ["agora-meyhanesi", "yanyali-fehmi-lokantasi", "develi-samatya"]}]}, "street": {"title": "La Rue — The Street", "desc": "Standing up: a mussel by the piece, kokoreç from a named usta, the wet burger, and the soup and the grill that see the night out.", "sections": [{"label": "Late night — after service", "desc": "Where the city eats at two in the morning: the soup against the rakı, and the grill of the drinking lanes.", "ids": ["lale-iskembecisi", "tarihi-mimoza-corbacisi", "tarihi-degustasyon-ocakbasi"]}, {"label": "Sur le pouce — the honest fast plate", "desc": "The standing canon, named counter by named counter: midye, kokoreç and the wet burger.", "ids": ["midyeci-ahmet-besiktas", "ozzies-1968-kokorec", "kizilkayalar-taksim"]}]}};
  const CATEGORIES = [{"key": "creme", "label": "La Crème de la Crème", "lead": "The three tables Istanbul is judged on: the two-star in Bomonti, the Pera roof, and the rebuilt classics in Karaköy. Book weeks out.", "story": {"title": "One argument, three answers", "story": "Every serious kitchen in this city is answering the same question: what Anatolian cooking is allowed to become. Mehmet Gürs answered it first, on the Pera roof, and coined the phrase New Anatolian Kitchen to do it. Maksut Aşkar answers it at Neolokal by going back for the regional recipes that had fallen out of use and rebuilding them, with a Green Star beside the star. Fatih Tutak, back in the city he was born in after Bangkok, Tokyo and Copenhagen, answers it with a twelve-step menu that changes on the micro-season. Eat at two of them and you will taste the argument.", "where": "TURK in Bomonti; Mikla on the Marmara Pera roof; Neolokal in Karaköy"}}, {"key": "rising", "label": "The 2026 wave", "lead": "The new guard: a fire inside a 19th-century passage, a starred chef's comfort food, and a neo-bistro across the water.", "story": {"title": "Opened into a crisis, cooked anyway", "story": "The wave that opened in 2025 and 2026 did it with the lira falling, and it shows in what they chose: fewer covers, one fire, a short card. Kontuar put an open hearth inside the Passage de Petits Champs, one of the arcades that link Tepebaşı to İstiklal. In the same passage, Neolokal's chef cooks schnitzel and goulash at Todos los Días, which sounds like a joke and is not. Across the water, two cooks back from France run Basta's neo-bistro off Bağdat Caddesi. None of them is a tasting menu; all three reward a call ahead.", "where": "Kontuar and Todos los Días in the Pera passage; Basta in Caddebostan"}}, {"key": "chefs-eat", "label": "Where the chefs eat", "lead": "Not the rankings: the addresses the city's own cooks give for their days off, and who says so.", "story": {"title": "Where the two stars go on a day off", "story": "When BBC Travel asked Fatih Tutak — then the only chef in Turkey holding two MICHELIN stars — where he actually eats, nothing on his list looked like TURK. His days off go to Ahmet Usta's coal trench in Maslak; his 'favourite restaurant in Turkey' is Nazende, just off Bağdat Caddesi, where Uluç Sakarya — a textiles man who decided at 50 to become a chef — shops the fish and vegetable markets every morning and cooks 'whatever he wants, but it's out of this world.' MICHELIN's inspectors reached the same address by their own route: the Guide Türkiye 2026 lists Nazende Cadde as a Bib Gourmand — the medal for eating well without paying for stars.", "where": "BBC Travel interview, November 2024 · MICHELIN Guide Türkiye 2026"}}, {"key": "ocakbasi", "label": "The fire counters — Ocakbaşı", "lead": "You sit at the coals and the usta cooks in front of you: the most Istanbul way to eat, on three counters.", "story": {"title": "The bar with a trench of coals in it", "story": "An ocakbaşı is a bar built round a charcoal trench, and the seats that matter are the ones at the trench. The usta works in front of you: liver first, as a test of the fire, then the skewers, then a lahmacun to close. The cooking came north with the twentieth-century migration from Adana, Urfa and Antep and is now so naturalised that visitors think it means Istanbul. It does not, and it does: three counters here, one on the Arnavutköy shore, one over the strait, one among the Maslak towers where a two-star chef spends his days off.", "where": "Tam in Arnavutköy; Mesai on İnönü Caddesi; Ahmet Ustam in Maslak"}}, {"key": "esnaf", "label": "Esnaf lokantası — the tradesman's table", "lead": "The rooms that matter more: a twelve-seat fire with a star, the Anatolian field-recording kitchen, and Antakya in exile.", "story": {"title": "The tradesman's lunch, taken seriously", "story": "An esnaf lokantası feeds the people who work the street: pots on the counter from the morning, you point, you eat, you go back to work. The three here took that form and made it a project. Çiya, opened by Musa Dağdeviren in 1998 by the Kadıköy market, collects regional recipes village by village and cooks them in their own traditions. Araf, twelve seats and one open fire, took a MICHELIN star. Casius cooks Antakya, which after the 2023 earthquakes carries a weight it did not have before. Go at lunch, when the counters are fullest.", "where": "Çiya and Araf in Kadıköy; Casius in Cihangir"}}, {"key": "kahvalti", "label": "Kahvaltı — the breakfast tables", "lead": "The breakfast table done seriously: a Van serpme house, the honest end of the Beşiktaş street, and kaymak by the water.", "story": {"title": "The kaymakçı who seeded a street", "story": "Pando Kaymak opened in the Beşiktaş market in 1895 — bianet calls it the neighbourhood's first breakfast shop — and Pandelli Şestakof, 'Pando Amca', ladled buffalo kaymak under a baby-blue shopfront on Mumcu Bakkal Sokak for decades, selling exactly three things: honey, kaymak and milk. The shop is gone; Culinary Backstreets ran its farewell in April 2018. The lineage is not: Şah İsmail Çakmak, who apprenticed under Pando usta in the 1970s, opened his own salon around the corner in 2002, and the two lanes Pando anchored — Şair Veysi and Çelebioğlu — now hold some thirty-five breakfast tables. One counter closed; a whole street of kahvaltı is its estate.", "where": "Beşiktaş çarşı — Mumcu Bakkal Sokak, then Şair Veysi and Çelebioğlu streets"}}, {"key": "ethnic", "label": "The other kitchens — Anatolia & beyond", "lead": "Siirt, Crete, the Black Sea and Damascus: the city eats in every direction it once ruled.", "story": {"title": "The quarter that crossed back", "story": "Saruja was the first quarter of Damascus built outside the ancient walls — laid out under the Mamluks in the 13th century, and later so thick with Ottoman-era mansions that it earned the nickname 'Little Istanbul'. Centuries on, Bilal Khalaf, a Damascene who lost his shops to the war, opened a restaurant on Fatih's Akşemsettin Caddesi — the street where Istanbul's Syrians rebuilt their high street, and named it Saruja. The quarter Damascus called Little Istanbul now names the Damascene table of Istanbul: the migration running back along its own road. Order anything with hot yogurt in it; that is the register Damascus never exported until now.", "where": "Saruja, Akşemsettin Cad. No:31-A, Fatih — https://www.google.com/maps/search/?api=1&query=Saruja+Restoran+Istanbul"}}, {"key": "late-night", "label": "Late night — after service", "lead": "Where the city eats at two in the morning: the soup against the rakı, and the grill of the drinking lanes.", "story": {"title": "The cure the meyhane makes necessary", "story": "A rakı night in this city has a fixed last chapter, and it is soup. İşkembe, tripe with garlic vinegar spooned in at the table, or kelle paça, slow-cooked cheek in a sharp garlic-butter broth, taken after midnight against the drink. The soup houses keep the hours the meyhane makes necessary: Lale in Tarlabaşı says it never closes, Mimoza in Samatya runs its pots until three. Between the bill and the soup, the drinking lanes of the Balık Pazarı have their own grill, reborn in 2024 under a young usta from Adana.", "where": "Lale in Tarlabaşı; Mimoza in Samatya; Degustasyon in the Balık Pazarı"}}, {"key": "quick-bites", "label": "Sur le pouce — the honest fast plate", "lead": "The standing canon, named counter by named counter: midye, kokoreç and the wet burger.", "story": {"title": "The wet burger has two fathers", "story": "Taksim's after-club food is the ıslak burger — a small garlicky burger soaked in tomato sauce and kept sweating in a steam-fogged glass case so it can be handed over in seconds. Two counters on the square both claim the invention. Kristal Büfe says founder Ahmet Yazıcı created it by accident, hurrying burgers into boiling tomato sauce and finding the sodden result sold better than the dry one. Kızılkayalar, trading since 1978, prints 'Islak Hamburgerin Mucidi' — inventor of the wet burger — across its own site. Nobody has settled it, and the late queue does not care: the case steams, the bun collapses, the night continues.", "where": "The büfe counters of Taksim Square"}}, {"key": "story", "label": "The old houses", "lead": "1890, 1912, 1919: the rooms where a century sits down to eat with you.", "story": {"title": "The houses that kept the line", "story": "Three rooms carry a date older than the Republic. A Rum sea captain, Asteri Dulidis, opened Agora in Balat in 1890, and three generations of his family kept it until 2001. Fehmi Efendi, whose family came from Yanya, now Ioannina in Greece, opened his lokanta in Kadıköy in 1919; his grandsons run it, and it took a Bib Gourmand in 2026. Arif Develi's grandfather took up the kebab in Gaziantep in 1912; the family brought it to Samatya, behind the Marmara walls, in 1966. Ask each for the dish it was founded on.", "where": "Agora in Balat; Yanyalı Fehmi in Kadıköy; Develi in Samatya"}}];
  const GROUPS = [{"key": "grande", "label": "Les Grandes Tables", "lead": "The tables you clear an evening for: the city's only two-star, two one-stars that argue about what Anatolian cooking may become, and the new wave that opened into a currency crisis and cooked anyway."}, {"key": "petite", "label": "Les Petites Tables", "lead": "Where this guide actually lives: the day-off addresses, the fire counters, the tradesman's tables, the breakfast houses, the kitchens of every direction the city once ruled, and the rooms that have fed it for a century."}, {"key": "street", "label": "La Rue — The Street", "lead": "Standing up: a mussel by the piece, kokoreç from a named usta, the wet burger, and the soup and the grill that see the night out."}];
